  --primary: #ff8163;
  --primary-foreground: #ffffff;
  --secondary: #453940;
  --secondary-foreground: #f1e9e5;
  --muted: #3a2f36;
  --muted-foreground: #d6c7bf;
  --accent: #fdb57e;
  --accent-foreground: #2c2025;
  --destructive: #e63745;
  --destructive-foreground: #ffffff;
  --border: #453940;
  --input: #453940;
  --ring: #ff8163;
  --chart-1: #ff8163;
  --chart-2: #fdb57e;
  --chart-3: #ffcba9;
  --chart-4: #ffad8f;
  --chart-5: #cf6b58;
  --radius: 0.625rem;
